-- =====================================================================
-- Tortas y Chocolates 3B - Esquema para PostgreSQL (Supabase)
-- Equivalente a database/01_schema.sql (MySQL).
--
-- Dónde ejecutarlo: Supabase > SQL Editor > New query > pegar > Run.
-- ATENCIÓN: borra las tablas del sistema si ya existen (y sus datos).
-- Después ejecutar 02_datos_prueba.sql o 02_usuario_inicial.sql.
--
-- Diferencias con MySQL:
--   * AUTO_INCREMENT  -> GENERATED BY DEFAULT AS IDENTITY
--   * ENUM            -> VARCHAR + CHECK
--   * TINYINT(1)      -> SMALLINT (0/1), así el código sirve para ambos motores
--   * DATETIME        -> TIMESTAMP
-- =====================================================================

-- Fechas y "hoy" en hora de Paraguay (Supabase usa UTC por defecto).
-- Rige para las conexiones nuevas.
ALTER DATABASE postgres SET timezone TO 'America/Asuncion';
SET TIME ZONE 'America/Asuncion';

DROP TABLE IF EXISTS movimientos_stock, detalle_compra, compras, ventas, delivery,
                     detalle_pedido, pedidos, ingredientes, proveedores, productos,
                     clientes, usuarios CASCADE;

CREATE TABLE usuarios (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         VARCHAR(100) NOT NULL,
    username       VARCHAR(50)  NOT NULL,
    password_hash  VARCHAR(100) NOT NULL,
    rol            VARCHAR(10)  NOT NULL CHECK (rol IN ('ADMIN','OPERADOR')),
    activo         SMALLINT     NOT NULL DEFAULT 1 CHECK (activo IN (0,1)),
    creado_en      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_usuarios_username UNIQUE (username)
);

CREATE TABLE clientes (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         VARCHAR(100) NOT NULL,
    telefono       VARCHAR(15)  NOT NULL,
    direccion      VARCHAR(200) NULL,
    email          VARCHAR(100) NULL,
    observaciones  VARCHAR(255) NULL,
    activo         SMALLINT     NOT NULL DEFAULT 1 CHECK (activo IN (0,1)),
    creado_en      TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_clientes_telefono UNIQUE (telefono)
);

CREATE TABLE productos (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         VARCHAR(100)  NOT NULL,
    descripcion    VARCHAR(255)  NULL,
    categoria      VARCHAR(10)   NOT NULL CHECK (categoria IN ('TORTA','CUPCAKE','CHOCOLATE','OTRO')),
    precio         NUMERIC(12,0) NOT NULL,
    costo_kilo     NUMERIC(12,0) NOT NULL DEFAULT 0,
    peso_kg        NUMERIC(6,3)  NOT NULL,
    activo         SMALLINT      NOT NULL DEFAULT 1 CHECK (activo IN (0,1)),
    CONSTRAINT uq_productos_nombre UNIQUE (nombre),
    CONSTRAINT ck_productos_precio CHECK (precio > 0),
    CONSTRAINT ck_productos_costo  CHECK (costo_kilo >= 0),
    CONSTRAINT ck_productos_peso   CHECK (peso_kg > 0)
);

CREATE TABLE proveedores (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         VARCHAR(100) NOT NULL,
    telefono       VARCHAR(15)  NOT NULL,
    direccion      VARCHAR(200) NULL,
    insumos        VARCHAR(255) NULL,
    activo         SMALLINT     NOT NULL DEFAULT 1 CHECK (activo IN (0,1)),
    CONSTRAINT uq_proveedores_nombre UNIQUE (nombre)
);

CREATE TABLE ingredientes (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre         VARCHAR(100)  NOT NULL,
    unidad         VARCHAR(10)   NOT NULL CHECK (unidad IN ('KG','G','L','ML','UNIDAD')),
    stock_actual   NUMERIC(10,3) NOT NULL DEFAULT 0,
    stock_minimo   NUMERIC(10,3) NOT NULL DEFAULT 0,
    proveedor_id   INTEGER NULL,
    activo         SMALLINT      NOT NULL DEFAULT 1 CHECK (activo IN (0,1)),
    CONSTRAINT uq_ingredientes_nombre UNIQUE (nombre),
    CONSTRAINT ck_ingredientes_stock  CHECK (stock_actual >= 0),
    CONSTRAINT ck_ingredientes_minimo CHECK (stock_minimo >= 0),
    CONSTRAINT fk_ingredientes_proveedor FOREIGN KEY (proveedor_id)
        REFERENCES proveedores (id) ON DELETE SET NULL
);

CREATE TABLE pedidos (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cliente_id     INTEGER NOT NULL,
    usuario_id     INTEGER NOT NULL,
    fecha_pedido   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_entrega  DATE NOT NULL,
    hora_entrega   TIME NOT NULL,
    tipo_entrega   VARCHAR(10) NOT NULL CHECK (tipo_entrega IN ('RETIRO','DELIVERY')),
    estado         VARCHAR(15) NOT NULL DEFAULT 'PENDIENTE'
                   CHECK (estado IN ('PENDIENTE','CONFIRMADO','EN_PREPARACION','LISTO',
                                     'EN_CAMINO','ENTREGADO','CANCELADO')),
    total          NUMERIC(12,0) NOT NULL DEFAULT 0,
    observaciones  VARCHAR(255) NULL,
    CONSTRAINT ck_pedidos_total CHECK (total >= 0),
    CONSTRAINT fk_pedidos_cliente FOREIGN KEY (cliente_id) REFERENCES clientes (id),
    CONSTRAINT fk_pedidos_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios (id)
);
CREATE INDEX idx_pedidos_entrega ON pedidos (fecha_entrega, hora_entrega);

CREATE TABLE detalle_pedido (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pedido_id        INTEGER NOT NULL,
    producto_id      INTEGER NOT NULL,
    cantidad         INTEGER NOT NULL,
    precio_unitario  NUMERIC(12,0) NOT NULL,
    subtotal         NUMERIC(12,0) NOT NULL,
    CONSTRAINT uq_detalle_pedido_producto UNIQUE (pedido_id, producto_id),
    CONSTRAINT ck_detalle_pedido_cantidad CHECK (cantidad > 0),
    CONSTRAINT ck_detalle_pedido_precio   CHECK (precio_unitario >= 0),
    CONSTRAINT fk_detalle_pedido_pedido FOREIGN KEY (pedido_id)
        REFERENCES pedidos (id) ON DELETE CASCADE,
    CONSTRAINT fk_detalle_pedido_producto FOREIGN KEY (producto_id)
        REFERENCES productos (id)
);

CREATE TABLE delivery (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pedido_id          INTEGER NOT NULL,
    direccion          VARCHAR(200) NOT NULL,
    telefono_contacto  VARCHAR(15)  NOT NULL,
    estado             VARCHAR(12)  NOT NULL DEFAULT 'PENDIENTE'
                       CHECK (estado IN ('PENDIENTE','PREPARANDO','EN_CAMINO','ENTREGADO','CANCELADO')),
    observaciones      VARCHAR(255) NULL,
    -- Sin "ON UPDATE": la aplicación lo actualiza en cada UPDATE
    actualizado_en     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_delivery_pedido UNIQUE (pedido_id),
    CONSTRAINT fk_delivery_pedido FOREIGN KEY (pedido_id)
        REFERENCES pedidos (id) ON DELETE CASCADE
);

CREATE TABLE ventas (
    id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pedido_id      INTEGER NOT NULL,
    usuario_id     INTEGER NOT NULL,
    fecha          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    metodo_pago    VARCHAR(15) NOT NULL CHECK (metodo_pago IN ('EFECTIVO','TRANSFERENCIA','OTRO')),
    total          NUMERIC(12,0) NOT NULL,
    CONSTRAINT uq_ventas_pedido UNIQUE (pedido_id),
    CONSTRAINT ck_ventas_total CHECK (total > 0),
    CONSTRAINT fk_ventas_pedido  FOREIGN KEY (pedido_id)  REFERENCES pedidos (id),
    CONSTRAINT fk_ventas_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios (id)
);
CREATE INDEX idx_ventas_fecha ON ventas (fecha);

CREATE TABLE compras (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    proveedor_id     INTEGER NOT NULL,
    usuario_id       INTEGER NOT NULL,
    fecha            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    fecha_recepcion  TIMESTAMP NULL,
    estado           VARCHAR(10) NOT NULL DEFAULT 'PENDIENTE'
                     CHECK (estado IN ('PENDIENTE','RECIBIDA','CANCELADA')),
    total            NUMERIC(12,0) NOT NULL DEFAULT 0,
    observaciones    VARCHAR(255) NULL,
    CONSTRAINT ck_compras_total CHECK (total >= 0),
    CONSTRAINT fk_compras_proveedor FOREIGN KEY (proveedor_id) REFERENCES proveedores (id),
    CONSTRAINT fk_compras_usuario   FOREIGN KEY (usuario_id)   REFERENCES usuarios (id)
);

CREATE TABLE detalle_compra (
    id               INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    compra_id        INTEGER NOT NULL,
    ingrediente_id   INTEGER NOT NULL,
    cantidad         NUMERIC(10,3) NOT NULL,
    costo_unitario   NUMERIC(12,0) NOT NULL DEFAULT 0,
    subtotal         NUMERIC(12,0) NOT NULL DEFAULT 0,
    CONSTRAINT uq_detalle_compra_ingrediente UNIQUE (compra_id, ingrediente_id),
    CONSTRAINT ck_detalle_compra_cantidad CHECK (cantidad > 0),
    CONSTRAINT ck_detalle_compra_costo    CHECK (costo_unitario >= 0),
    CONSTRAINT fk_detalle_compra_compra FOREIGN KEY (compra_id)
        REFERENCES compras (id) ON DELETE CASCADE,
    CONSTRAINT fk_detalle_compra_ingrediente FOREIGN KEY (ingrediente_id)
        REFERENCES ingredientes (id)
);

CREATE TABLE movimientos_stock (
    id                INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ingrediente_id    INTEGER NOT NULL,
    usuario_id        INTEGER NOT NULL,
    compra_id         INTEGER NULL,
    fecha             TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tipo              VARCHAR(10) NOT NULL CHECK (tipo IN ('AJUSTE','COMPRA')),
    cantidad          NUMERIC(10,3) NOT NULL,
    stock_resultante  NUMERIC(10,3) NOT NULL,
    motivo            VARCHAR(200) NULL,
    CONSTRAINT ck_movimientos_cantidad CHECK (cantidad <> 0),
    CONSTRAINT fk_movimientos_ingrediente FOREIGN KEY (ingrediente_id) REFERENCES ingredientes (id),
    CONSTRAINT fk_movimientos_usuario     FOREIGN KEY (usuario_id)     REFERENCES usuarios (id),
    CONSTRAINT fk_movimientos_compra      FOREIGN KEY (compra_id)      REFERENCES compras (id)
);

-- ---------------------------------------------------------------------
-- Seguridad: Supabase publica las tablas del esquema "public" en su API
-- REST. Con RLS activado y sin políticas, esa API no puede leer ni escribir
-- nada. La aplicación se conecta con el usuario "postgres", que no está
-- sujeto a RLS, así que sigue funcionando normalmente.
-- ---------------------------------------------------------------------
ALTER TABLE usuarios          ENABLE ROW LEVEL SECURITY;
ALTER TABLE clientes          ENABLE ROW LEVEL SECURITY;
ALTER TABLE productos         ENABLE ROW LEVEL SECURITY;
ALTER TABLE proveedores       ENABLE ROW LEVEL SECURITY;
ALTER TABLE ingredientes      ENABLE ROW LEVEL SECURITY;
ALTER TABLE pedidos           ENABLE ROW LEVEL SECURITY;
ALTER TABLE detalle_pedido    ENABLE ROW LEVEL SECURITY;
ALTER TABLE delivery          ENABLE ROW LEVEL SECURITY;
ALTER TABLE ventas            ENABLE ROW LEVEL SECURITY;
ALTER TABLE compras           ENABLE ROW LEVEL SECURITY;
ALTER TABLE detalle_compra    ENABLE ROW LEVEL SECURITY;
ALTER TABLE movimientos_stock ENABLE ROW LEVEL SECURITY;
